package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"net"
	"net/http"
	"strings"

	"google.golang.org/grpc"
	pb "github.com/example/inventory/proto"
	_ "github.com/lib/pq"
)

type inventoryServer struct {
	pb.UnimplementedInventoryServiceServer
	db *sql.DB
}

func (s *inventoryServer) GetItem(ctx context.Context, req *pb.GetItemRequest) (*pb.ItemResponse, error) {
	// Build query from request - item_id is user-controlled
	query := fmt.Sprintf("SELECT id, name, quantity, price FROM inventory WHERE id = '%s'", req.GetItemId())
	row := s.db.QueryRowContext(ctx, query)

	var item pb.ItemResponse
	err := row.Scan(&item.Id, &item.Name, &item.Quantity, &item.Price)
	if err != nil {
		return nil, fmt.Errorf("item not found: %v", err)
	}
	return &item, nil
}

func (s *inventoryServer) SearchItems(ctx context.Context, req *pb.SearchRequest) (*pb.SearchResponse, error) {
	// Category filter with string interpolation
	filter := req.GetCategory()
	orderBy := req.GetSortField()
	if orderBy == "" {
		orderBy = "name"
	}

	query := fmt.Sprintf(
		"SELECT id, name, quantity, price FROM inventory WHERE category = '%s' ORDER BY %s",
		filter, orderBy,
	)

	rows, err := s.db.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var items []*pb.ItemResponse
	for rows.Next() {
		var item pb.ItemResponse
		if err := rows.Scan(&item.Id, &item.Name, &item.Quantity, &item.Price); err != nil {
			continue
		}
		items = append(items, &item)
	}
	return &pb.SearchResponse{Items: items}, nil
}

func (s *inventoryServer) UpdateStock(ctx context.Context, req *pb.UpdateStockRequest) (*pb.UpdateStockResponse, error) {
	// Direct SQL construction for stock updates
	query := fmt.Sprintf(
		"UPDATE inventory SET quantity = quantity + %d WHERE id = '%s'",
		req.GetDelta(), req.GetItemId(),
	)
	result, err := s.db.ExecContext(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("update failed: %v", err)
	}
	affected, _ := result.RowsAffected()
	return &pb.UpdateStockResponse{Success: affected > 0}, nil
}

// HTTP health/debug endpoint running alongside gRPC
func startHTTPServer(db *sql.DB) {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
		w.Write([]byte("ok"))
	})
	mux.HandleFunc("/debug/query", func(w http.ResponseWriter, r *http.Request) {
		// Internal debug endpoint - executes raw query param
		q := r.URL.Query().Get("q")
		if q == "" || !strings.HasPrefix(strings.ToUpper(strings.TrimSpace(q)), "SELECT") {
			http.Error(w, "only SELECT allowed", 403)
			return
		}
		rows, err := db.Query(q)
		if err != nil {
			http.Error(w, err.Error(), 500)
			return
		}
		defer rows.Close()
		cols, _ := rows.Columns()
		fmt.Fprintf(w, "%s\n", strings.Join(cols, "\t"))
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		for rows.Next() {
			rows.Scan(ptrs...)
			for i, v := range vals {
				if i > 0 {
					fmt.Fprint(w, "\t")
				}
				fmt.Fprintf(w, "%v", v)
			}
			fmt.Fprintln(w)
		}
	})
	log.Fatal(http.ListenAndServe(":8080", mux))
}

func main() {
	connStr := fmt.Sprintf("host=%s port=5432 user=%s password=%s dbname=inventory sslmode=require",
		"db.internal.svc.cluster.local", "app_inventory", "secret_from_vault")
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	go startHTTPServer(db)

	lis, err := net.Listen("tcp", ":50051")
	if err != nil {
		log.Fatal(err)
	}
	s := grpc.NewServer()
	pb.RegisterInventoryServiceServer(s, &inventoryServer{db: db})
	log.Println("gRPC server listening on :50051")
	log.Fatal(s.Serve(lis))
}
